128	        $where = 'WHERE w.deleted_at IS NULL';
129	        $params = [];
130	
131	        if (($filters['is_visible'] ?? '') !== '' && $filters['is_visible'] !== null) {
132	            $where .= ' AND w.is_visible = :is_visible';
133	            $params[':is_visible'] = (int) $filters['is_visible'];
134	        }
135	        if (($filters['is_notice'] ?? '') !== '' && $filters['is_notice'] !== null) {
136	            $where .= ' AND w.is_notice = :is_notice';
137	            $params[':is_notice'] = (int) $filters['is_notice'];
138	        }
139	        if (!empty($filters['searchKeyword'])) {
140	            $where .= ' AND (w.title LIKE :kw OR w.client LIKE :kw)';
141	            $params[':kw'] = '%' . $filters['searchKeyword'] . '%';
142	        }
143	        $awardF = isset($filters['is_awarded']) ? (string) $filters['is_awarded'] : '';
144	        if ($awardF === 'Y') {
145	            $where .= " AND w.is_awarded = 'Y'";
146	        } elseif ($awardF === 'N') {
147	            $where .= " AND (w.is_awarded IS NULL OR w.is_awarded != 'Y')";
148	        }
149	
150	        $sort = AdminListSort::normalize(AdminListSort::SORT_SORT_NO_DESC, isset($filters['sort']) ? (string) $filters['sort'] : null);
151	        $orderSql = AdminListSort::orderBySortable('w', $sort);
152	
153	        $totalStmt = $db->prepare("SELECT COUNT(*) FROM nb_works w $where");
154	        $totalStmt->execute($params);
155	        $total = (int) $totalStmt->fetchColumn();
156	
157	        $stmt = $db->prepare(
158	            "SELECT w.* FROM nb_works w $where $orderSql
159	             LIMIT :offset, :perPage"
160	        );
