165	        $stmt->bindValue(':perPage', $perPage, PDO::PARAM_INT);
166	        $stmt->execute();
167	
168	        return ['rows' => $stmt->fetchAll(PDO::FETCH_ASSOC), 'totalCount' => $total];
169	    }
