203	    /**
204	     * 관리자/API 기본 정렬(sort_no DESC, id DESC) 순서를 유지한 채 sort_no 를 1..n 으로 촘촘히 다시 매김.
205	     *
206	     * @return list<array{id: int, from: int, to: int}>
207	     */
208	    public static function planRebalanceSortNos(): array
209	    {
210	        $db = DB::getInstance();
211	        $stmt = $db->query(
212	            'SELECT id, sort_no FROM nb_works WHERE deleted_at IS NULL ORDER BY sort_no DESC, id DESC'
213	        );
214	        $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);
215	        $n = count($rows);
216	        $plan = [];
217	        $assign = $n;
218	        foreach ($rows as $r) {
219	            $plan[] = [
220	                'id' => (int) $r['id'],
221	                'from' => (int) $r['sort_no'],
222	                'to' => $assign,
223	            ];
224	            $assign--;
225	        }
226	
227	        return $plan;
228	    }
