232	     */
233	    private static function ensureSortNoUndoTable(\PDO $db): void
234	    {
235	        $db->exec(
236	            'CREATE TABLE IF NOT EXISTS `nb_works_sort_no_undo` (
237	                `works_id` int NOT NULL,
238	                `sort_no` int NOT NULL,
239	                PRIMARY KEY (`works_id`)
240	            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci'
241	        );
242	    }
