244	    private static function snapshotSortNosToUndo(\PDO $db): void
245	    {
246	        self::ensureSortNoUndoTable($db);
247	        $db->exec('DELETE FROM nb_works_sort_no_undo');
248	        $db->exec(
249	            'INSERT INTO nb_works_sort_no_undo (works_id, sort_no)
250	             SELECT id, sort_no FROM nb_works WHERE deleted_at IS NULL'
251	        );
252	    }
253	
254	    /**
255	     * 스냅샷 후 현재 목록 순서대로 sort_no 를 n..1 로 재부여 (중간 빈 번호 제거).
256	     *
257	     * @return int 갱신한 행 수
258	     */
259	    public static function rebalanceSortNos(): int
260	    {
261	        $db = DB::getInstance();
262	        $db->beginTransaction();
263	        try {
264	            self::snapshotSortNosToUndo($db);
265	            $stmt = $db->query(
266	                'SELECT id FROM nb_works WHERE deleted_at IS NULL ORDER BY sort_no DESC, id DESC'
267	            );
268	            /** @var list<int|string> $ids */
269	            $ids = $stmt->fetchAll(PDO::FETCH_COLUMN);
270	            $cnt = count($ids);
271	            if ($cnt === 0) {
272	                $db->commit();
273	
274	                return 0;
275	            }
276	            $phase1 = $db->prepare(
277	                'UPDATE nb_works SET sort_no = :sn, updated_at = NOW() WHERE id = :id AND deleted_at IS NULL'
278	            );
279	            foreach ($ids as $id) {
280	                $i = (int) $id;
281	                $phase1->execute([':sn' => -$i, ':id' => $i]);
282	            }
283	            $v = $cnt;
284	            foreach ($ids as $id) {
285	                $phase1->execute([':sn' => $v, ':id' => (int) $id]);
286	                $v--;
287	            }
288	            $db->commit();
289	
290	            return $cnt;
291	        } catch (\Throwable $e) {
292	            $db->rollBack();
293	            throw $e;
294	        }
295	    }
296	
297	    /**
298	     * 마지막 rebalanceSortNos() 직전에 저장된 sort_no 로 되돌림 (스냅샷이 비어 있으면 0).
299	     *
300	     * @return int 복원 시도한 행 수(스냅샷 행 수)
301	     */
302	    public static function restoreSortNosFromUndo(): int
303	    {
304	        $db = DB::getInstance();
305	        self::ensureSortNoUndoTable($db);
306	        $stmt = $db->query('SELECT works_id, sort_no FROM nb_works_sort_no_undo');
307	        $pairs = $stmt->fetchAll(PDO::FETCH_ASSOC);
308	        if ($pairs === []) {
309	            return 0;
310	        }
311	        $db->beginTransaction();
312	        try {
313	            $phase = $db->prepare(
314	                'UPDATE nb_works SET sort_no = :sn, updated_at = NOW() WHERE id = :id AND deleted_at IS NULL'
315	            );
316	            foreach ($pairs as $r) {
317	                $wid = (int) $r['works_id'];
318	                $phase->execute([':sn' => -$wid, ':id' => $wid]);
319	            }
320	            foreach ($pairs as $r) {
321	                $phase->execute([
322	                    ':sn' => (int) $r['sort_no'],
323	                    ':id' => (int) $r['works_id'],
324	                ]);
325	            }
326	            $db->commit();
327	
328	            return count($pairs);
329	        } catch (\Throwable $e) {
330	            $db->rollBack();
331	            throw $e;
332	        }
333	    }
